import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def blocks(g):
    H=len(g);W=len(g[0]);seen=set();out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and (i,j) not in seen:
                col=g[i][j];st=[(i,j)];cells=[]
                while st:
                    c,e=st.pop()
                    if (c,e) in seen: continue
                    seen.add((c,e));cells.append((c,e))
                    for dc,dd in ((1,0),(-1,0),(0,1),(0,-1)):
                        nc,nw=c+dc,e+dd
                        if 0<=nc<H and 0<=nw<W and g[nc][nw]==col and (nc,nw) not in seen: st.append((nc,nw))
                out.append({'col':col,'cells':cells})
    return out
def f(g):
    bs=blocks(g)
    wsum=sum(max(e for _,e in b['cells'])-min(e for _,e in b['cells'])+1 for b in bs)
    h=max(max(r for r,_ in b['cells'])-min(r for r,_ in b['cells'])+1 for b in bs)
    off=0; grid=[[0]*wsum for _ in range(h)]
    for b in bs:
        w_=max(e for _,e in b['cells'])-min(e for _,e in b['cells'])+1
        for r,c in b['cells']:
            grid[r-min(r for r,_ in b['cells'])][c-min(e for _,e in b['cells'])+off]=b['col']
        off+=w_
    return grid
print(json.dumps(f(G['Demo pair 1 input'])))
